<?php
/**
 * Parker's Physics hub page.
 *
 * A page with the slug "parkers-physics" (or any page using the
 * "Parker's Physics Hub" template) renders page-parkers-physics.php:
 * live space-weather and earthquake readouts, the page's own content,
 * the Living Earth sims, the full simulation catalog
 * (inc/parkers-catalog.php, generated by tools/build-parkers-catalog.py),
 * audiences, principles, articles that feature the sims, and sign-up.
 *
 * This file holds the helpers the template uses, plus the wiring that
 * points the rest of the site at the hub.
 *
 * @package Infinity
 * @since 3.21.0
 */

if (!defined('ABSPATH')) {
    exit;
}

require_once INFINITY_DIR . '/inc/parkers-catalog.php';

/**
 * The hub page, or null when it hasn't been created yet.
 */
function infinity_parkers_hub_page() {
    static $page = false;
    if (false !== $page) {
        return $page;
    }
    $page = get_page_by_path('parkers-physics');
    if (!$page || 'publish' !== $page->post_status) {
        $ids  = get_posts(array(
            'post_type'      => 'page',
            'post_status'    => 'publish',
            'meta_key'       => '_wp_page_template',
            'meta_value'     => 'page-parkers-physics.php',
            'posts_per_page' => 1,
            'fields'         => 'ids',
        ));
        $page = $ids ? get_post($ids[0]) : null;
    }
    return $page;
}

/**
 * Hub URL, or '' when the page doesn't exist.
 */
function infinity_parkers_hub_url() {
    $page = infinity_parkers_hub_page();
    return $page ? get_permalink($page) : '';
}

/**
 * Whether the current request is the hub.
 */
function infinity_is_parkers_hub() {
    return is_page('parkers-physics') || is_page_template('page-parkers-physics.php');
}

/**
 * The catalog with absolute URLs.
 */
function infinity_parkers_catalog() {
    $urls = infinity_property_urls();
    $base = trailingslashit($urls['parkers']);
    $data = infinity_parkers_catalog_data();
    foreach ($data as &$section) {
        foreach ($section['sims'] as &$sim) {
            $sim['url'] = $base . ltrim($sim['path'], '/');
        }
        unset($sim);
    }
    unset($section);
    return apply_filters('infinity_parkers_catalog', $data);
}

function infinity_parkers_catalog_count() {
    $n = 0;
    foreach (infinity_parkers_catalog() as $section) {
        $n += count($section['sims']);
    }
    return $n;
}

/**
 * Fetch a JSON feed, cached. Failures are cached briefly too, so a slow
 * upstream can't hold every page view hostage.
 */
function infinity_parkers_feed($key, $url, $ttl = 600) {
    $cache_key = 'infinity_pp_feed_' . $key;
    $cached    = get_transient($cache_key);
    if (false !== $cached) {
        return 'fail' === $cached ? null : $cached;
    }
    $res = wp_remote_get($url, array('timeout' => 4, 'headers' => array('Accept' => 'application/json')));
    if (is_wp_error($res) || 200 !== wp_remote_retrieve_response_code($res)) {
        set_transient($cache_key, 'fail', 2 * MINUTE_IN_SECONDS);
        return null;
    }
    $data = json_decode(wp_remote_retrieve_body($res), true);
    if (!is_array($data)) {
        set_transient($cache_key, 'fail', 2 * MINUTE_IN_SECONDS);
        return null;
    }
    set_transient($cache_key, $data, $ttl);
    return $data;
}

/**
 * Live readouts for the hub hero. Each: label, value, unit, note, sim
 * path on Parker's Physics, tone (calm|active|storm). Missing feeds
 * simply drop out.
 */
function infinity_parkers_live_readouts() {
    $out = array();

    // Planetary Kp, one-minute estimate (NOAA SWPC)
    $kp = infinity_parkers_feed('kp', 'https://services.swpc.noaa.gov/json/planetary_k_index_1m.json');
    if ($kp) {
        $last = end($kp);
        if (isset($last['estimated_kp'])) {
            $v    = (float) $last['estimated_kp'];
            $g    = $v >= 5 ? (int) min(5, floor($v) - 4) : 0;
            $out[] = array(
                'label' => __('Geomagnetic activity', 'infinity'),
                'value' => number_format_i18n($v, 1),
                'unit'  => 'Kp',
                'note'  => $g ? sprintf(__('G%d storm in progress', 'infinity'), $g) : ($v >= 4 ? __('Active, aurora possible at high latitude', 'infinity') : __('Quiet', 'infinity')),
                'path'  => 'auroracle.html',
                'tone'  => $g ? 'storm' : ($v >= 4 ? 'active' : 'calm'),
                'cta'   => 'live_kp',
            );
        }
    }

    // Solar wind speed at L1 (NOAA SWPC)
    $sw = infinity_parkers_feed('wind', 'https://services.swpc.noaa.gov/products/summary/solar-wind-speed.json');
    if ($sw && isset($sw[0]['proton_speed'])) {
        $v     = (int) $sw[0]['proton_speed'];
        $out[] = array(
            'label' => __('Solar wind', 'infinity'),
            'value' => number_format_i18n($v),
            'unit'  => 'km/s',
            'note'  => $v >= 600 ? __('Fast stream arriving', 'infinity') : ($v >= 450 ? __('Elevated', 'infinity') : __('Slow, typical', 'infinity')),
            'path'  => 'space-weather.html',
            'tone'  => $v >= 600 ? 'storm' : ($v >= 450 ? 'active' : 'calm'),
            'cta'   => 'live_wind',
        );
    }

    // Latest M4.5+ earthquake (USGS)
    $eq = infinity_parkers_feed('quake', 'https://earthquake.usgs.gov/earthquakes/feed/v1.0/summary/4.5_day.geojson');
    if ($eq && !empty($eq['features'][0]['properties'])) {
        $p     = $eq['features'][0]['properties'];
        $ago   = isset($p['time']) ? human_time_diff((int) ($p['time'] / 1000), time()) : '';
        $out[] = array(
            'label' => __('Latest strong quake', 'infinity'),
            'value' => 'M' . number_format_i18n((float) $p['mag'], 1),
            'unit'  => '',
            'note'  => trim(sprintf(
                /* translators: 1: place, 2: time ago */
                __('%1$s, %2$s ago', 'infinity'),
                isset($p['place']) ? $p['place'] : '',
                $ago
            ), ', '),
            'path'  => 'earth-interior.html',
            'tone'  => (float) $p['mag'] >= 7 ? 'storm' : ((float) $p['mag'] >= 6 ? 'active' : 'calm'),
            'cta'   => 'live_quake',
        );
    }

    return apply_filters('infinity_parkers_live_readouts', $out);
}

/**
 * Posts that feature Parker's Physics: flagged on save (they use the
 * sim shortcodes or link to parkersphysics.com) or tagged
 * parkers-physics.
 */
function infinity_parkers_flag_post($post_id, $post) {
    if (wp_is_post_revision($post_id) || 'post' !== $post->post_type) {
        return;
    }
    $features = (function_exists('infinity_living_earth_sims_in') && infinity_living_earth_sims_in($post->post_content))
        || has_shortcode($post->post_content, 'parkers_next')
        || false !== stripos($post->post_content, 'parkersphysics.com');
    if ($features) {
        update_post_meta($post_id, '_infinity_features_parkers', 1);
    } else {
        delete_post_meta($post_id, '_infinity_features_parkers');
    }
}
add_action('save_post', 'infinity_parkers_flag_post', 10, 2);

function infinity_parkers_articles($count = 6) {
    $flagged = get_posts(array(
        'post_type'      => 'post',
        'posts_per_page' => $count,
        'meta_key'       => '_infinity_features_parkers',
        'fields'         => 'ids',
        'no_found_rows'  => true,
    ));
    $tagged = get_posts(array(
        'post_type'      => 'post',
        'posts_per_page' => $count,
        'tag'            => 'parkers-physics',
        'fields'         => 'ids',
        'no_found_rows'  => true,
    ));
    // Older posts that only mention it in the title
    $titled = get_posts(array(
        'post_type'      => 'post',
        'posts_per_page' => $count,
        's'              => "Parker's Physics",
        'search_columns' => array('post_title'),
        'fields'         => 'ids',
        'no_found_rows'  => true,
    ));
    $ids = array_values(array_unique(array_merge($flagged, $tagged, $titled)));
    if (!$ids) {
        return array();
    }
    return get_posts(array(
        'post_type'      => 'post',
        'post__in'       => $ids,
        'orderby'        => 'date',
        'posts_per_page' => $count,
        'no_found_rows'  => true,
    ));
}

/**
 * Assets, only on the hub.
 */
function infinity_parkers_hub_assets() {
    if (!infinity_is_parkers_hub()) {
        return;
    }
    wp_enqueue_style('infinity-parkers-sims', infinity_css_url('assets/css/parkers-sims.css'), array('infinity-style'), INFINITY_VERSION);
    wp_enqueue_style('infinity-parkers-hub', infinity_css_url('assets/css/parkers-hub.css'), array('infinity-parkers-sims'), INFINITY_VERSION);
    wp_enqueue_script('infinity-parkers-hub', INFINITY_URI . '/assets/js/parkers-hub.js', array(), INFINITY_VERSION, array('in_footer' => true, 'strategy' => 'defer'));
}
add_action('wp_enqueue_scripts', 'infinity_parkers_hub_assets', 21);

/**
 * schema.org for the hub: a CollectionPage whose ItemList is every
 * simulation, each a free WebApplication.
 */
function infinity_parkers_hub_schema() {
    if (!infinity_is_parkers_hub() || defined('WPSEO_VERSION') || class_exists('RankMath') || defined('AIOSEO_VERSION')) {
        return;
    }
    $items = array();
    $i     = 0;
    foreach (infinity_parkers_catalog() as $section) {
        foreach ($section['sims'] as $sim) {
            $items[] = array(
                '@type'    => 'ListItem',
                'position' => ++$i,
                'item'     => array(
                    '@type'               => 'WebApplication',
                    'name'                => $sim['title'],
                    'url'                 => $sim['url'],
                    'description'         => $sim['blurb'],
                    'applicationCategory' => 'EducationalApplication',
                    'operatingSystem'     => 'Any (web browser)',
                    'isAccessibleForFree' => true,
                ),
            );
        }
    }
    $schema = array(
        '@context'   => 'https://schema.org',
        '@type'      => 'CollectionPage',
        'name'       => get_the_title(),
        'url'        => get_permalink(),
        'about'      => array(
            '@type' => 'Organization',
            'name'  => "Parker's Physics",
            'url'   => trailingslashit(infinity_property_urls()['parkers']),
        ),
        'mainEntity' => array(
            '@type'           => 'ItemList',
            'numberOfItems'   => $i,
            'itemListElement' => $items,
        ),
    );
    printf('<script type="application/ld+json">%s</script>' . "\n", wp_json_encode($schema, JSON_UNESCAPED_SLASHES | JSON_UNESCAPED_UNICODE));
}
add_action('wp_head', 'infinity_parkers_hub_schema', 7);

/**
 * The simulation post type's archive (/simulations/) is empty on this
 * site, while the homepage sends people there to "browse simulations".
 * Once the hub exists, an empty archive forwards to it.
 */
function infinity_parkers_redirect_empty_archive() {
    if (!is_post_type_archive('simulation') || have_posts()) {
        return;
    }
    $hub = infinity_parkers_hub_url();
    if ($hub) {
        wp_safe_redirect($hub, 302);
        exit;
    }
}
add_action('template_redirect', 'infinity_parkers_redirect_empty_archive');

/**
 * Admin: offer to create the hub page in one click.
 */
function infinity_parkers_hub_notice() {
    if (!current_user_can('publish_pages') || infinity_parkers_hub_page()) {
        return;
    }
    $screen = get_current_screen();
    if (!$screen || !in_array($screen->id, array('dashboard', 'edit-page', 'themes'), true)) {
        return;
    }
    $url = wp_nonce_url(admin_url('admin-post.php?action=infinity_create_parkers_hub'), 'infinity_create_parkers_hub');
    printf(
        '<div class="notice notice-info"><p>%1$s <a class="button button-primary" href="%2$s">%3$s</a></p></div>',
        esc_html__("The theme has a Parker's Physics hub page (live readouts, the full simulation catalog, sign-up). It isn't published yet.", 'infinity'),
        esc_url($url),
        esc_html__('Create the hub page', 'infinity')
    );
}
add_action('admin_notices', 'infinity_parkers_hub_notice');

function infinity_parkers_create_hub() {
    if (!current_user_can('publish_pages') || !check_admin_referer('infinity_create_parkers_hub')) {
        wp_die(esc_html__('Not allowed.', 'infinity'));
    }
    $page = infinity_parkers_hub_page();
    if (!$page) {
        $id = wp_insert_post(array(
            'post_type'    => 'page',
            'post_status'  => 'publish',
            'post_title'   => "Parker's Physics",
            'post_name'    => 'parkers-physics',
            'post_excerpt' => sprintf(
                /* translators: %d: number of simulations */
                __("%d free physics simulations driven by live NASA, NOAA and USGS data: space weather, a changing Earth, the solar system and deep space, running in your browser.", 'infinity'),
                infinity_parkers_catalog_count()
            ),
            'post_content' => "<!-- wp:paragraph -->\n<p>" . esc_html__("Parker's Physics is my physics simulation hub: real models fed by live data from the satellites and observatories watching the Sun, the Earth and the sky. Everything below opens in your browser and runs on its own. Pick a place to start.", 'infinity') . "</p>\n<!-- /wp:paragraph -->",
            'meta_input'   => array('_wp_page_template' => 'page-parkers-physics.php'),
        ), true);
        if (is_wp_error($id)) {
            wp_die(esc_html($id->get_error_message()));
        }
        $page = get_post($id);
    }
    wp_safe_redirect(get_edit_post_link($page->ID, 'url'));
    exit;
}
add_action('admin_post_infinity_create_parkers_hub', 'infinity_parkers_create_hub');
